insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3607e0e3-45a4-4d78-a6e9-b50b636f8cc3', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', null, 'topic'::public.curated_course_node_type, 'The Big Question: Defining the Topic and the Problem', 'Interdisciplinary inquiry starts with a problem that cannot be understood adequately through one field alone. Students learn to turn a broad theme into a researchable, consequential question with boundaries, stakeholders, and a shared vocabulary.', 0),
  ('8a458d9f-9e3a-434e-8b9b-e0faba6362f1', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '3607e0e3-45a4-4d78-a6e9-b50b636f8cc3', 'subtopic'::public.curated_course_node_type, 'Theme and problem space', 'Distinguish a compelling topic from a specific problem that can guide sustained inquiry.', 0),
  ('2297ed0d-0ccf-48bd-9e35-76e6542247dc', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '8a458d9f-9e3a-434e-8b9b-e0faba6362f1', 'concept'::public.curated_course_node_type, 'Possible themes: climate resilience, AI and society, migration, public health, democracy, or urban futures', null, 0),
  ('ac286a7e-ac70-4414-8c54-a23020ec3aea', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '8a458d9f-9e3a-434e-8b9b-e0faba6362f1', 'concept'::public.curated_course_node_type, 'Problem situations, symptoms, causes, consequences, and contested meanings', null, 1),
  ('b993113e-2876-46e0-84d8-cf8d8f11b4dc', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '8a458d9f-9e3a-434e-8b9b-e0faba6362f1', 'concept'::public.curated_course_node_type, 'Why the problem exceeds a single discipline', null, 2),
  ('2613ad0b-a52f-4410-bc03-a19fc7625e75', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '3607e0e3-45a4-4d78-a6e9-b50b636f8cc3', 'subtopic'::public.curated_course_node_type, 'Question formulation', 'Develop questions that invite explanation, interpretation, evaluation, and action.', 1),
  ('f9bde134-8503-4827-8083-4e527541ac19', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '2613ad0b-a52f-4410-bc03-a19fc7625e75', 'concept'::public.curated_course_node_type, 'Descriptive, causal, interpretive, normative, and design questions', null, 0),
  ('038f0632-85ed-4ff3-afd3-7c252d36f10d', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '2613ad0b-a52f-4410-bc03-a19fc7625e75', 'concept'::public.curated_course_node_type, 'Question scope, feasibility, significance, and uncertainty', null, 1),
  ('16334424-b080-42f2-b7e1-564c8dc92052', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '2613ad0b-a52f-4410-bc03-a19fc7625e75', 'concept'::public.curated_course_node_type, 'Nested questions and a shared inquiry agenda', null, 2),
  ('0c0f5cc6-aff4-4630-b7d2-b29f431456c0', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '3607e0e3-45a4-4d78-a6e9-b50b636f8cc3', 'subtopic'::public.curated_course_node_type, 'Boundaries and scale', 'Decide where the study begins and ends without pretending the problem is isolated.', 2),
  ('7f4eae34-a740-415c-92ee-af8f431cedad', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0c0f5cc6-aff4-4630-b7d2-b29f431456c0', 'concept'::public.curated_course_node_type, 'Local, regional, national, planetary, and historical scales', null, 0),
  ('2b4b7dfa-6d4e-4dea-8608-f952fb4cb20f', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0c0f5cc6-aff4-4630-b7d2-b29f431456c0', 'concept'::public.curated_course_node_type, 'Population, institution, ecosystem, technology, and time boundaries', null, 1),
  ('46e44398-4e42-4dfa-9257-f2640cce0379', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0c0f5cc6-aff4-4630-b7d2-b29f431456c0', 'concept'::public.curated_course_node_type, 'Boundary choices, exclusions, and implications', null, 2),
  ('0c1f41f1-c9b1-4e4d-8e86-27f583bbdeb7', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '3607e0e3-45a4-4d78-a6e9-b50b636f8cc3', 'subtopic'::public.curated_course_node_type, 'Stakeholders and publics', 'Identify who experiences, defines, governs, studies, or can change the problem.', 3),
  ('fcf0682f-9439-4f9b-8ea1-c94ff1f083e0', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0c1f41f1-c9b1-4e4d-8e86-27f583bbdeb7', 'concept'::public.curated_course_node_type, 'Affected communities, decision makers, experts, organizations, and nonhuman interests', null, 0),
