  ('cace1a00-388b-4389-8e86-2ee6b15f58bb', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0c1f41f1-c9b1-4e4d-8e86-27f583bbdeb7', 'concept'::public.curated_course_node_type, 'Stakeholder maps and engagement priorities', null, 2),
  ('d2b636fc-f110-4c30-8959-df8b1b0a82a6', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '3607e0e3-45a4-4d78-a6e9-b50b636f8cc3', 'subtopic'::public.curated_course_node_type, 'Inquiry charter', 'Create a living agreement about purpose, evidence, collaboration, and deliverables.', 4),
  ('ed14ca52-621e-4680-b2d3-50a811d875f2', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'd2b636fc-f110-4c30-8959-df8b1b0a82a6', 'concept'::public.curated_course_node_type, 'Central question, subquestions, outcomes, and audience', null, 0),
  ('96882ef3-80ac-4418-931b-c46ea1a05bdf', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'd2b636fc-f110-4c30-8959-df8b1b0a82a6', 'concept'::public.curated_course_node_type, 'Assumptions, terms, unknowns, and success criteria', null, 1),
  ('5146fca9-1857-44e6-aa5e-5793f1837cd9', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'd2b636fc-f110-4c30-8959-df8b1b0a82a6', 'concept'::public.curated_course_node_type, 'Research ethics, team norms, milestones, and revision process', null, 2),
  ('03f75b1f-7dc1-4947-9ecb-887d5666c7d4', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', null, 'topic'::public.curated_course_node_type, 'Disciplines, Epistemologies, and Ways of Knowing', 'Disciplines are not simply collections of facts; they organize questions, methods, evidence, values, and standards of explanation. Students learn to recognize these architectures so that integration respects real differences rather than flattening them.', 1),
  ('def16e24-e29d-4612-b08a-ed5557e64385', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '03f75b1f-7dc1-4947-9ecb-887d5666c7d4', 'subtopic'::public.curated_course_node_type, 'Anatomy of a discipline', 'Examine how fields define legitimate problems and knowledge.', 0),
  ('05b9639f-baab-4a2c-adac-76ddca905fa4', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'def16e24-e29d-4612-b08a-ed5557e64385', 'concept'::public.curated_course_node_type, 'Objects of study and characteristic questions', null, 0),
  ('2aa4df97-9674-44a6-bf9f-d8c043481dae', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'def16e24-e29d-4612-b08a-ed5557e64385', 'concept'::public.curated_course_node_type, 'Core concepts, theories, methods, genres, and institutions', null, 1),
  ('66c6e693-8cad-497d-adfd-9e30f78d0a0b', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'def16e24-e29d-4612-b08a-ed5557e64385', 'concept'::public.curated_course_node_type, 'Standards of evidence, explanation, and expertise', null, 2),
  ('50260d02-cba2-4ef3-ba95-f7758c44ae46', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '03f75b1f-7dc1-4947-9ecb-887d5666c7d4', 'subtopic'::public.curated_course_node_type, 'Epistemologies', 'Compare accounts of what can be known and how claims become warranted.', 1),
