  ('7b0dc2c1-5421-4bd7-8bc3-87d89e50b18b', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '50260d02-cba2-4ef3-ba95-f7758c44ae46', 'concept'::public.curated_course_node_type, 'Certainty, probability, ambiguity, and pluralism', null, 2),
