  ('b7ade903-6e6e-48c3-b23b-6d209d3a7082', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'eb7883dc-b9a5-46df-a930-6133c478fc8e', 'concept'::public.curated_course_node_type, 'Individual, institutional, cultural, ecological, and technological explanations', null, 1),
  ('0ea036f1-7c72-45e4-b605-1ccde04a522f', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'eb7883dc-b9a5-46df-a930-6133c478fc8e', 'concept'::public.curated_course_node_type, 'Normal science, anomalies, and paradigm change', null, 2),
