  ('660913ec-4f0b-4af2-bd8c-7df52ffce4a9', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '03f75b1f-7dc1-4947-9ecb-887d5666c7d4', 'subtopic'::public.curated_course_node_type, 'Intellectual humility', 'Treat expertise as necessary but partial.', 4),
