  ('36562d23-e9d2-4c7f-819a-d6a69097821d', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0d76129d-d050-4006-b55e-28c497661618', 'concept'::public.curated_course_node_type, 'Aesthetic form, empathy, estrangement, and interpretation', null, 2),
