  ('22579864-2e96-4647-82f2-133df96c8b39', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '60875113-f172-4f0c-9961-6304a53034fc', 'subtopic'::public.curated_course_node_type, 'Levels of social explanation', 'Locate mechanisms across persons, networks, organizations, and institutions.', 0),
  ('ac986965-c208-4d6c-b957-062913538412', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '22579864-2e96-4647-82f2-133df96c8b39', 'concept'::public.curated_course_node_type, 'Micro, meso, and macro levels', null, 0),
  ('f88743fd-37fb-4d60-91ea-124e20e0f4fb', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '22579864-2e96-4647-82f2-133df96c8b39', 'concept'::public.curated_course_node_type, 'Agency, structure, norms, incentives, and identity', null, 1),
  ('265c7370-5be5-4804-8dca-283d43f0e912', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '22579864-2e96-4647-82f2-133df96c8b39', 'concept'::public.curated_course_node_type, 'Feedback between individual and collective outcomes', null, 2),
  ('eb371b0d-9a17-4c30-ab60-91bc3cb4f094', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '60875113-f172-4f0c-9961-6304a53034fc', 'subtopic'::public.curated_course_node_type, 'Institutions and governance', 'Analyze how formal and informal rules distribute authority and resources.', 1),
  ('de32633c-7109-4615-80e4-a985a90138b3', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'eb371b0d-9a17-4c30-ab60-91bc3cb4f094', 'concept'::public.curated_course_node_type, 'States, markets, firms, schools, families, and civil society', null, 0),
  ('f1ec7860-9590-4d81-a201-72b976aa5618', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'eb371b0d-9a17-4c30-ab60-91bc3cb4f094', 'concept'::public.curated_course_node_type, 'Policy design, implementation, and administrative capacity', null, 1),
  ('cfd608b4-51b9-4610-9a1a-71026ce75855', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'eb371b0d-9a17-4c30-ab60-91bc3cb4f094', 'concept'::public.curated_course_node_type, 'Institutional change, lock-in, and legitimacy', null, 2),
  ('5398a17f-8e60-44cc-a419-19c2696d551f', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '60875113-f172-4f0c-9961-6304a53034fc', 'subtopic'::public.curated_course_node_type, 'Power and inequality', 'Examine how benefits, burdens, recognition, and voice are distributed.', 2),
  ('74afdd13-cb86-4492-92e9-f58578c127e7', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '5398a17f-8e60-44cc-a419-19c2696d551f', 'concept'::public.curated_course_node_type, 'Class, race, gender, disability, citizenship, and intersectionality', null, 0),
  ('dc588487-b683-465c-866c-4a4bf986379f', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '5398a17f-8e60-44cc-a419-19c2696d551f', 'concept'::public.curated_course_node_type, 'Structural, relational, discursive, and coercive power', null, 1),
  ('6e7ffee5-4afb-4d91-bf37-d56249844ef8', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '5398a17f-8e60-44cc-a419-19c2696d551f', 'concept'::public.curated_course_node_type, 'Measurement, lived experience, and cumulative disadvantage', null, 2),
  ('38042057-f16a-481c-8146-ac8d5c27d42b', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '60875113-f172-4f0c-9961-6304a53034fc', 'subtopic'::public.curated_course_node_type, 'Behavior and decision making', 'Study choice in social context rather than assuming fully rational actors.', 3),
