  ('34fca065-59f4-4b10-bc95-8036ef882572', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', null, 'topic'::public.curated_course_node_type, 'Natural and Quantitative Lenses: Systems, Measurement, and Evidence', 'Scientific and quantitative approaches help characterize mechanisms, patterns, constraints, and uncertainty. Students learn to use numbers critically—checking definitions, models, uncertainty, and values embedded in measurement.', 4),
  ('4f19591c-7602-4b1d-bae8-6ce1becfaacb', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '34fca065-59f4-4b10-bc95-8036ef882572', 'subtopic'::public.curated_course_node_type, 'Scientific modeling', 'Represent selected features of reality to explain or predict.', 0),
  ('a20ac08a-1d5d-4134-8b1f-6045c9676181', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '4f19591c-7602-4b1d-bae8-6ce1becfaacb', 'concept'::public.curated_course_node_type, 'Variables, mechanisms, assumptions, boundaries, and scales', null, 0),
  ('06a2e984-31c7-4871-bcdc-fb51622fd816', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '4f19591c-7602-4b1d-bae8-6ce1becfaacb', 'concept'::public.curated_course_node_type, 'Conceptual, mathematical, computational, and physical models', null, 1),
  ('bccadfbd-b2e6-427e-b44c-67caefec275b', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '4f19591c-7602-4b1d-bae8-6ce1becfaacb', 'concept'::public.curated_course_node_type, 'Model validation, limitations, and domain of applicability', null, 2),
  ('7312ff2a-f6dd-44a4-8f1b-754ddf26e24d', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '34fca065-59f4-4b10-bc95-8036ef882572', 'subtopic'::public.curated_course_node_type, 'Measurement and indicators', 'Ask what a number represents, how it was produced, and what it excludes.', 1),
  ('f2e8915a-670d-438a-a71d-9895a579904b', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '7312ff2a-f6dd-44a4-8f1b-754ddf26e24d', 'concept'::public.curated_course_node_type, 'Operational definitions, units, validity, and reliability', null, 0),
  ('02f19da2-bff1-4253-ae11-dfc264b5060a', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '7312ff2a-f6dd-44a4-8f1b-754ddf26e24d', 'concept'::public.curated_course_node_type, 'Proxies, composite indicators, baselines, and denominators', null, 1),
  ('d7341517-eb93-45ae-b5ca-952d39e81958', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '7312ff2a-f6dd-44a4-8f1b-754ddf26e24d', 'concept'::public.curated_course_node_type, 'Measurement error and missing data', null, 2),
  ('aee53cb9-b85b-4872-bc02-209a578774a6', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '34fca065-59f4-4b10-bc95-8036ef882572', 'subtopic'::public.curated_course_node_type, 'Data interpretation', 'Read patterns while resisting overclaiming.', 2),
  ('da644f46-73b6-4f52-ae93-6acd8dda3b60', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'aee53cb9-b85b-4872-bc02-209a578774a6', 'concept'::public.curated_course_node_type, 'Distributions, rates, uncertainty intervals, and effect sizes', null, 0),
