  ('a865edc9-1f0f-4aad-8828-2de0b020541f', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'aee53cb9-b85b-4872-bc02-209a578774a6', 'concept'::public.curated_course_node_type, 'Visualization choices and misleading comparisons', null, 2),
