  ('8fd4cfa4-3741-40fd-8ffb-70e4ccea7977', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '044b68c7-b628-4866-b7f5-17598a495344', 'concept'::public.curated_course_node_type, 'Energy and material flows', null, 0),
  ('c4a1320a-5d0a-49a8-9974-b953f3b0f0b4', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '044b68c7-b628-4866-b7f5-17598a495344', 'concept'::public.curated_course_node_type, 'Ecosystems, resilience, thresholds, and feedback', null, 1),
  ('be0cb7fc-606d-4519-a11f-53d26f2b5c96', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '044b68c7-b628-4866-b7f5-17598a495344', 'concept'::public.curated_course_node_type, 'Climate, biodiversity, pollution, and resource use', null, 2),
