  ('646a7781-0652-4892-af8f-0de2ddbc40b4', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '66475f0c-9f90-4a99-ab8a-0476cf48d01c', 'concept'::public.curated_course_node_type, 'Benefit, harm, risk, and quality-of-life metrics', null, 0),
  ('76882da4-3921-4b6a-9b72-745378b8a111', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '66475f0c-9f90-4a99-ab8a-0476cf48d01c', 'concept'::public.curated_course_node_type, 'Monetization and nonmonetary values', null, 1),
  ('471c3268-095f-460d-bfb9-c4a1d24bd029', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '66475f0c-9f90-4a99-ab8a-0476cf48d01c', 'concept'::public.curated_course_node_type, 'Distribution, uncertainty, and ethical limits of aggregation', null, 2),
