  ('a69e05d0-7c3d-45dc-9981-ab029f3d9cca', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', '0465a89d-76a9-4477-9045-05ce6a2c4fb0', 'concept'::public.curated_course_node_type, 'Sketching, composing, performance, fabrication, and iteration', null, 0),
