  ('bd7e95b7-23ea-4bb8-b6d3-c1383659b24f', 'b4c5d6e7-8f9a-4b65-8e45-5c6d7e8f9a65', 'facc9f3a-ad41-4bb9-8834-3ed0793426c0', 'concept'::public.curated_course_node_type, 'How-might-we questions and assumption reversal', null, 0),
